def fill_entire_row(row_idx):
    """Fill entire row based on horizontal segments"""
    row = input_grid[row_idx]

    # Find all non-zero positions with their colors
    positions = [(c, row[c]) for c in range(15) if row[c] != 0]

    if len(positions) < 2:
        return

    sorted_positions = sorted(positions)

    for i in range(len(sorted_positions)):
        curr_col = sorted_positions[i][0]
        curr_color = sorted_positions[i][1]

        # Check what's immediately to the left
        if i > 0:
            prev_col = sorted_positions[i-1][0]
            prev_color = sorted_positions[i-1][1]

            gap_start = prev_col + 1
            gap_end = curr_col - 1
            if gap_start <= gap_end:
                dist_to_prev_end = gap_start - prev_col - 1
                dist_to_curr_start = curr_col - gap_end

                if dist_to_prev_end <= dist_to_curr_start:
                    fill_color = prev_color
                else:
                    fill_color = curr_color

                for c in range(gap_start, gap_end + 1):
                    output[row_idx][c] = fill_color

        # Check what's to the right
        for j in range(i+1, len(sorted_positions)):
            next_col = sorted_positions[j][0]
            next_color = sorted_positions[j][1]

            gap_start = curr_col + 1
            gap_end = next_col - 1
            if gap_start <= gap_end:
                dist_to_next_start = next_col - gap_start
                dist_to_curr_end = gap_end - curr_col

                if dist_to_curr_end <= dist_to_next_start:
                    fill_color = curr_color
                else:
                    fill_color = next_color

                for c in range(gap_start, gap_end + 1):
                    output[row_idx][c] = fill_color
                break

