# Fix the logic - simple approach: merge same-color segments, fill between them
def fill_row_segmentally(row_idx):
    """Fill each row by merging same-color segments"""
    row = input_grid[row_idx]

    # Find continuous segments: (start, end, color)
    segments = []
    i = 0
    while i < 15:
        if row[i] != 0:
            start = i
            color = row[i]
            while i < 15 and row[i] == color:
                i += 1
            segments.append((start, i-1, color))
        else:
            i += 1

    if len(segments) < 1:
        return

    if len(segments) == 1:
        # Single segment - no gap filling needed
        for c in range(segments[0][0], segments[0][1] + 1):
            output[row_idx][c] = segments[0][2]
        return

    # Multiple segments - fill gaps between adjacent ones
    for j in range(len(segments) - 1):
        seg1 = segments[j]
        seg2 = segments[j+1]

        gap_start = seg1[1] + 1
        gap_end = seg2[0] - 1

        if gap_start <= gap_end:
            # Fill gap with appropriate color
            # Use the color whose segment edge is closest to the gap
            dist_left_to_gap_end = seg1[1] + 1 - gap_start  # 0 if immediately adjacent
            dist_right_to_gap_start = gap_end - seg2[0] + 1

            # Actually simpler: which side does the gap touch more?
            # Gap starts after seg1 ends → distance from gap start to seg1's right edge = 0
            # Gap ends before seg2 starts → distance from gap end to seg2's left edge = 0

            # The midpoint of gap
            gap_mid = (gap_start + gap_end) // 2

            dist_to_seg1 = gap_mid - seg1[1]  # Distance from mid to left segment
            dist_to_seg2 = seg2[0] - gap_mid   # Distance from mid to right segment

            if dist_to_seg1 <= dist_to_seg2:
                fill_color = seg1[2]
            else:
                fill_color = seg2[2]

            for c in range(gap_start, gap_end + 1):
                output[row_idx][c] = fill_color

