    for c in range(15):
        if row[c] != 0:
            output[row_idx][c] = row[c]

    # Find continuous segments: (start, end, color)
    segments = []
    i = 0
    while i < 15:
        if row[i] != 0:
            start = i
            color = row[i]
            while i < 15 and row[i] == color:
                i += 1
            segments.append((start, i-1, color))
        else:
            i += 1

    if len(segments) < 2:
        return

    # Fill gaps between consecutive segments
    for j in range(len(segments) - 1):
        seg1 = segments[j]
        seg2 = segments[j+1]

        gap_start = seg1[1] + 1
        gap_end = seg2[0] - 1

        if gap_start <= gap_end:
            # Calculate which side's color to use based on distance
            gap_mid = (gap_start + gap_end) // 2

            dist_to_seg1 = gap_mid - seg1[1]
            dist_to_seg2 = seg2[0] - gap_mid

            if dist_to_seg1 <= dist_to_seg2:
                fill_color = seg1[2]
            else:
                fill_color = seg2[2]

            for c in range(gap_start, gap_end + 1):
                output[row_idx][c] = fill_color

