def run_algorithm(grid):
    output = [[0]*15 for _ in range(15)]

    # Fill each row
    for r in range(15):
        row = grid[r]

        # Copy original pixels
        for c in range(15):
            if row[c] != 0:
                output[r][c] = row[c]

        # Find segments
        segments = []
        i = 0
        while i < 15:
            if row[i] != 0:
                start = i
                color = row[i]
                while i < 15 and row[i] == color:
                    i += 1
                segments.append((start, i-1, color))
            else:
                i += 1

        if len(segments) < 2:
            continue

        # Fill gaps
        for j in range(len(segments) - 1):
            seg1 = segments[j]
            seg2 = segments[j+1]

            gap_start = seg1[1] + 1
            gap_end = seg2[0] - 1

            if gap_start <= gap_end:
                gap_mid = (gap_start + gap_end) // 2
                dist_to_seg1 = gap_mid - seg1[1]
                dist_to_seg2 = seg2[0] - gap_mid

                if dist_to_seg1 <= dist_to_seg2:
                    fill_color = seg1[2]
                else:
                    fill_color = seg2[2]

                for c in range(gap_start, gap_end + 1):
                    output[r][c] = fill_color

    return output

